"use client";
/**
 * Built-in sound effects, synthesised in the browser (no samples, no licences
 * needed: every sound is generated by this code). Rendered once with an
 * OfflineAudioContext, then kept as a normal audio asset so it plays,
 * mixes and exports like any other sound.
 */
import { peakGain } from "../audioMix";

export interface SfxDef {
  id: string;
  label: string;
  group: "Whooshes" | "Hits" | "Pops & clicks" | "UI & notifications" | "Fun";
  duration: number;
  build: (ctx: OfflineAudioContext) => void;
}

/* ---------- building blocks ---------- */

function noise(ctx: BaseAudioContext, seconds: number, seed = 1): AudioBuffer {
  const len = Math.max(1, Math.round(seconds * ctx.sampleRate));
  const b = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = b.getChannelData(0);
  let x = seed * 9301 + 49297;
  for (let i = 0; i < len; i++) { x = (x * 9301 + 49297) % 233280; d[i] = (x / 233280) * 2 - 1; }
  return b;
}

function env(ctx: BaseAudioContext, g: GainNode, at: number, attack: number, hold: number, release: number, peak = 1) {
  g.gain.setValueAtTime(0.0001, at);
  g.gain.exponentialRampToValueAtTime(peak, at + Math.max(0.002, attack));
  g.gain.setValueAtTime(peak, at + attack + hold);
  g.gain.exponentialRampToValueAtTime(0.0001, at + attack + hold + release);
}

function tone(ctx: OfflineAudioContext, type: OscillatorType, f0: number, f1: number, at: number, dur: number, peak = 0.6, attack = 0.005, out: AudioNode = ctx.destination) {
  const o = ctx.createOscillator();
  o.type = type;
  o.frequency.setValueAtTime(f0, at);
  if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), at + dur);
  const g = ctx.createGain();
  env(ctx, g, at, attack, 0, Math.max(0.01, dur - attack), peak);
  o.connect(g).connect(out);
  o.start(at);
  o.stop(at + dur + 0.05);
}

function noiseSweep(ctx: OfflineAudioContext, at: number, dur: number, f0: number, f1: number, q: number, peak: number, shape: "swell" | "hit" = "swell", seed = 1) {
  const src = ctx.createBufferSource();
  src.buffer = noise(ctx, dur + 0.1, seed);
  const bp = ctx.createBiquadFilter();
  bp.type = "bandpass";
  bp.Q.value = q;
  bp.frequency.setValueAtTime(f0, at);
  bp.frequency.exponentialRampToValueAtTime(f1, at + dur);
  const g = ctx.createGain();
  if (shape === "swell") env(ctx, g, at, dur * 0.55, 0, dur * 0.45, peak);
  else env(ctx, g, at, 0.003, 0, dur, peak);
  src.connect(bp).connect(g).connect(ctx.destination);
  src.start(at);
}

function stereoWide(ctx: OfflineAudioContext): AudioNode {
  // a tiny delay on one side for width
  const merger = ctx.createChannelMerger(2);
  const input = ctx.createGain();
  const d = ctx.createDelay(0.05);
  d.delayTime.value = 0.012;
  input.connect(merger, 0, 0);
  input.connect(d).connect(merger, 0, 1);
  merger.connect(ctx.destination);
  return input;
}

/* ---------- the library ---------- */

