    lfo.connect(lg).connect(o.frequency); o.frequency.value = 330;
    const g = c.createGain(); env(c, g, 0, 0.005, 0.1, 0.6, 0.6); o.connect(g).connect(c.destination); o.start(0); lfo.start(0); o.stop(0.8); lfo.stop(0.8);
