export const sfxById = (id: string) => SFX.find((s) => s.id === id);

/** Render one effect to an AudioBuffer (stereo, 48 kHz), peaking at most at about −1 dBFS. */
export async function renderSfx(def: SfxDef, sampleRate = 48000): Promise<AudioBuffer> {
  const ctx = new OfflineAudioContext(2, Math.ceil(def.duration * sampleRate), sampleRate);
  def.build(ctx);
  return capPeak(await ctx.startRendering());
}

/** Scale a rendered buffer down if it would clip (layered tones can sum past 1). */
export function capPeak(buf: AudioBuffer): AudioBuffer {
  const chans = Array.from({ length: buf.numberOfChannels }, (_, i) => buf.getChannelData(i));
  const g = peakGain(chans);
  if (g < 1) for (const d of chans) for (let i = 0; i < d.length; i++) d[i] *= g;
  return buf;
}

/** 16-bit PCM WAV, for storing generated audio as a normal asset. */
export function encodeWav(buf: AudioBuffer): Blob {
  const ch = buf.numberOfChannels;
  const len = buf.length;
  const data = new DataView(new ArrayBuffer(44 + len * ch * 2));
  const w = (o: number, s: string) => { for (let i = 0; i < s.length; i++) data.setUint8(o + i, s.charCodeAt(i)); };
  w(0, "RIFF"); data.setUint32(4, 36 + len * ch * 2, true); w(8, "WAVE"); w(12, "fmt ");
  data.setUint32(16, 16, true); data.setUint16(20, 1, true); data.setUint16(22, ch, true);
  data.setUint32(24, buf.sampleRate, true); data.setUint32(28, buf.sampleRate * ch * 2, true);
  data.setUint16(32, ch * 2, true); data.setUint16(34, 16, true); w(36, "data"); data.setUint32(40, len * ch * 2, true);
  const chans = Array.from({ length: ch }, (_, i) => buf.getChannelData(i));
  let o = 44;
  for (let i = 0; i < len; i++) for (let c = 0; c < ch; c++) { const v = Math.max(-1, Math.min(1, chans[c][i])); data.setInt16(o, v < 0 ? v * 0x8000 : v * 0x7fff, true); o += 2; }
  return new Blob([data.buffer], { type: "audio/wav" });
}
